const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Southern California region
  const socal = ee.Geometry.Polygon([
    [[-121.0, 32.5], [-121.0, 35.5], [-114.0, 35.5], [-114.0, 32.5], [-121.0, 32.5]]
  ]);

  // 2. Load MODIS LST data for both periods
  const lst2003 = ee.ImageCollection('MODIS/006/MOD11A1')
    .filterDate('2003-04-14', '2003-04-22')
    .filterBounds(socal)
    .select('LST_Day_1km');

  const lst2004 = ee.ImageCollection('MODIS/006/MOD11A1')
    .filterDate('2004-04-14', '2004-04-22')
    .filterBounds(socal)
    .select('LST_Day_1km');

  const size2003 = lst2003.size().getInfo();
  const size2004 = lst2004.size().getInfo();

  console.log('2003 Images: ' + size2003);
  console.log('2004 Images: ' + size2004);

  // Check if collections are empty
  if (size2003 === 0 || size2004 === 0) {
    console.log('One or both periods have no data.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Apply scaling factor (MODIS LST scale: 0.02, units: Kelvin)
  const scaleLST = function(image) {
    return image.multiply(0.02).copyProperties(image, ['system:time_start']);
  };

  const lst2003Scaled = lst2003.map(scaleLST);
  const lst2004Scaled = lst2004.map(scaleLST);

  // 4. Calculate mean composites
  const mean2003 = lst2003Scaled.mean();
  const mean2004 = lst2004Scaled.mean();

  // 5. Calculate statistics for both periods
  const stats2003 = mean2003.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: socal,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2004 = mean2004.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: socal,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const temp2003 = stats2003.LST_Day_1km_mean;
  const count2003 = stats2003.LST_Day_1km_count;
  const temp2004 = stats2004.LST_Day_1km_mean;
  const count2004 = stats2004.LST_Day_1km_count;

  console.log('2003 Mean LST (K): ' + (temp2003 ? temp2003.toFixed(2) : 'null'));
  console.log('2003 Valid Pixels: ' + count2003);
  console.log('2004 Mean LST (K): ' + (temp2004 ? temp2004.toFixed(2) : 'null'));
  console.log('2004 Valid Pixels: ' + count2004);

  // 6. Check for no valid pixels
  if (count2003 === 0 || count2004 === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Check for invalid temperature values
  if (temp2003 === null || temp2004 === null || 
      temp2003 < 200 || temp2003 > 400 || 
      temp2004 < 200 || temp2004 > 400) {
    console.log('Invalid temperature calculation.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Compare temperatures
  const tempDiff = temp2004 - temp2003;
  console.log('Temperature Difference (2004-2003): ' + tempDiff.toFixed(2) + ' K');

  if (temp2004 > temp2003) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
